request_approval_message.beforeRequest:
const url = inputs.resumeUrl + '/confirm?chat_id=' + encodeURIComponent(inputs.chat_id);
const parse_mode = inputs.parse_mode && inputs.parse_mode !== 'None' ? inputs.parse_mode : undefined;
request.body = {chat_id: inputs.chat_id, text: inputs.message, parse_mode, reply_markup: {inline_keyboard: [[{text: 'Review & Respond', url}]]}};
return request;
